# Features computed this long after the submission was sent were computed
# for an older contest (the first opening of the panel), not when the
# submission was sent or judged, so it is unknown whether it was pasted.
BACKFILL_DELAY = timedelta(days=1)


def mark_backfilled(apps, schema_editor):
    SubmissionFeatures = apps.get_model("llmdetect", "SubmissionFeatures")
    unknown = []
    for features in SubmissionFeatures.objects.filter(pasted=False).select_related("submission").only("id", "computed_at", "submission__date").iterator():
        if features.computed_at - features.submission.date > BACKFILL_DELAY:
            unknown.append(features.id)
    for start in range(0, len(unknown), 1000):
        SubmissionFeatures.objects.filter(id__in=unknown[start : start + 1000]).update(paste_known=False)


